/* @lc app=leetcode id=2146 lang=kotlin */
class Solution { fun highestRankedKItems(grid: Array<IntArray>, pricing: IntArray, start: IntArray, k: Int): List<List<Int>> = mutableListOf<IntArray>().also { items -> java.util.ArrayDeque<Triple<Int, Int, Int>>().also { q -> q.add(Triple(start[0], start[1], 0)) }.let { q -> Array(grid.size) { BooleanArray(grid[0].size) }.also { vis -> vis[start[0]].set(start[1], true) }.let { vis -> generateSequence { q.poll() }.forEach { (r, c, d) -> (if (grid[r][c] in pricing[0]..pricing[1]) items.add(intArrayOf(d, grid[r][c], r, c)) else Unit).also { listOf(r - 1 to c, r + 1 to c, r to c - 1, r to c + 1).forEach { (nr, nc) -> if (nr in grid.indices && nc in grid[0].indices && grid[nr][nc] != 0 && !vis[nr][nc]) q.add(Triple(nr, nc, d + 1)).also { vis[nr].set(nc, true) } } } } } }.sortedWith(compareBy({ it[0] }, { it[1] }, { it[2] }, { it[3] })).take(k).map { listOf(it[2], it[3]) } }